PAGE = """<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Контроль документов</title><style>
:root{--blue:#0079C2;--ink:#102a43;--paper:#f5f8fa;--red:#c92a2a;--yellow:#f0b429;--orange:#e67e22;--manual:#2374ab}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px system-ui,sans-serif}.shell{max-width:960px;margin:auto;padding:32px 20px}.mast{border-left:8px solid var(--blue);padding:8px 16px;margin-bottom:24px}.mast h1{margin:0;font-size:clamp(26px,5vw,42px)}.mast p{margin:6px 0 0}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#bdd0dc}.step{background:white;padding:18px}.step b{color:var(--blue)}form{display:grid;gap:16px;background:white;padding:24px;border:1px solid #d8e3e8}label{font-weight:650}input,button{font:inherit;padding:11px;border:1px solid #9bb3c3;border-radius:3px}button{background:var(--blue);color:white;border-color:var(--blue);font-weight:700;cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #f0b429;outline-offset:2px}.legend{display:flex;flex-wrap:wrap;gap:12px;margin-top:22px}.tag{padding:7px 10px;border-left:5px solid}.red{border-color:var(--red)}.yellow{border-color:var(--yellow)}.orange{border-color:var(--orange)}.manual{border-color:var(--manual)}#status{min-height:24px;margin-top:16px}@media(max-width:620px){.steps{grid-template-columns:1fr}.shell{padding:20px 14px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}</style><main class="shell"><header class="mast"><h1>Контроль документов</h1><p>Загрузите исходный файл и целевой отчёт. Исходники остаются без изменений.</p></header><section class="steps" aria-label="Порядок работы"><div class="step"><b>01 Файлы</b><br>Две книги Excel</div><div class="step"><b>02 Этап</b><br>Проверка и расчёт</div><div class="step"><b>03 Решение</b><br>Review и выгрузка</div></section><form id="job"><label>Исходный документ <input name="source" type="file" accept=".xlsx,.xlsm" required></label><label>Целевой отчёт <input name="target" type="file" accept=".xlsx,.xlsm" required></label><label>Этап <input name="stage" value="13.1" inputmode="decimal" required></label><button>Запустить проверку</button></form><p id="status" role="status"></p><aside class="legend" aria-label="Категории расхождений"><span class="tag red">Красный — единицы</span><span class="tag yellow">Жёлтый — без изменений</span><span class="tag orange">Оранжевый — стоимость</span><span class="tag manual">Синий — ручная проверка</span></aside></main><script>document.querySelector('#job').onsubmit=async e=>{e.preventDefault();let r=await fetch('/jobs',{method:'POST',body:new FormData(e.target)}),p=await r.json();document.querySelector('#status').textContent=p.error||'Задача создана. ID: '+p.job_id}</script></html>"""
